import{describe,it,expect}from"vitest";import{AWARD_ENCYCLOPEDIA,getAwardDetailsByKey,searchAwardsAndRecipients,filterAwardsByCategory}from"../../frontend/js-modules/national-awards.js";describe("National Bravery Awards Explorer Dataset",()=>{it("contains the 'national-bravery-awards' dataset entry",()=>{const e=AWARD_ENCYCLOPEDIA["national-bravery-awards"];expect(e).toBeDefined(),expect(e.id).toBe("national-bravery-awards"),expect(e.name).toContain("National Bravery Awards"),expect(e.category).toBe("children"),expect(e.establishedYear).toBe("1957")}),it("contains all required dataset sections (Eligibility, History, Medal Design, Winners, Facts)",()=>{const e=getAwardDetailsByKey("national-bravery-awards");expect(e).not.toBeNull(),expect(e.eligibility).toBeTruthy(),expect(e.history).toBeTruthy(),expect(e.medalDesign).toBeTruthy(),expect(Array.isArray(e.notableWinners)).toBe(!0),expect(e.notableWinners.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.interestingFacts)).toBe(!0),expect(e.interestingFacts.length).toBeGreaterThanOrEqual(3)}),it("includes famous child heroes in dataset",()=>{const e=getAwardDetailsByKey("national-bravery-awards").notableWinners.map(e=>e.name);expect(e.some(e=>e.includes("Harish Chandra Mehra"))).toBe(!0),expect(e.some(e=>e.includes("Geeta Chopra"))).toBe(!0),expect(e.some(e=>e.includes("Resham Fatima"))).toBe(!0),expect(e.some(e=>e.includes("Zen Gunratan Sadavarte"))).toBe(!0)}),it("searches and filters National Bravery Awards accurately",()=>{const e=searchAwardsAndRecipients("National Bravery Awards");expect(e.length).toBeGreaterThanOrEqual(1),expect(e.some(e=>"national-bravery-awards"===e.id)).toBe(!0);const a=searchAwardsAndRecipients("Harish Chandra Mehra");expect(a.length).toBeGreaterThanOrEqual(1),expect(a[0].id).toBe("national-bravery-awards");const t=filterAwardsByCategory("children");expect(t.some(e=>"national-bravery-awards"===e.id)).toBe(!0)})});